const $=s=>document.querySelector(s);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(window.libraryScope ? 'wd-account-'+window.libraryScope+'-'+key : key))??fallback}catch{return fallback}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.messageTimer);window.messageTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function store(key,value){if(window.libraryViewOnly)return true;try{localStorage.setItem(window.libraryScope ? 'wd-account-'+window.libraryScope+'-'+key : key,JSON.stringify(value));if(!window.cloudHydrating&&(key==='wd-books'||key==='wd-memories'))window.cloudQueue?.();return true}catch{toast('This browser is out of storage. Try a smaller photo or video.');return false}}
let books=read('wd-books',null);
if(!books?.length){const oldPieces=read('wd-scrap-draft',[]),oldDiary=read('wd-writing-draft',{left:read('wd-draft',{}).text||'',right:''}),oldEntries=read('wd-entries',[]);books=oldPieces.length||oldDiary.left||oldDiary.right||oldEntries.length?[{id:crypto.randomUUID(),title:'My little book of life',category:'Personal',color:'#efadf6',entries:oldEntries,draft:{pieces:oldPieces,diary:oldDiary,entryId:null},updated:new Date().toISOString()}]:[]}
function isReadOnlyBook(book=activeBook()){return !!book?.isSample||!window.diaryAuth?.canEdit()}
function requireBookEdit(book=activeBook()){if(book?.isSample){toast('This sample is read-only. Choose Make your own book to start.');return false}return window.diaryAuth?.requireSignedIn()||false}

function ensureSpreads(book){if(!book.spreads?.length)book.spreads=[{id:crypto.randomUUID(),heading:'',diary:structuredClone(book.draft?.diary||{left:'',right:''}),pieces:structuredClone(book.draft?.pieces||[]),entryId:book.draft?.entryId||null}];book.activeSpread=Math.max(0,Math.min(book.spreads.length-1,Number(book.activeSpread)||0));return book.spreads[book.activeSpread]}
books.forEach(ensureSpreads);
let introSample=books.find(b=>b.isSample&&b.sampleVersion===DEMO_VERSION);
if(!introSample){const oldSamples=books.filter(b=>b.isSample);if(oldSamples.length){const archive=read('wd-removed-books',[]);oldSamples.forEach(book=>{if(!archive.some(item=>item.book.id===book.id))archive.push({book:structuredClone(book),removedAt:new Date().toISOString()})});if(store('wd-removed-books',archive))books=books.filter(b=>!b.isSample)}introSample=createSampleBook();books.push(introSample);store('wd-books',books)}
introSample.activeSpread=0;
let activeBookId=introSample.id;

function activeBook(){return books.find(b=>b.id===activeBookId)}
let pieces=structuredClone(ensureSpreads(activeBook()).pieces||[]),entries=activeBook().entries||[],memories=read('wd-memories',[]),selected=null,entryId=ensureSpreads(activeBook()).entryId||null;
function persistLibrary(){if(isReadOnlyBook())return true;const spread=ensureSpreads(activeBook());Object.assign(spread,{pieces:structuredClone(pieces),diary:structuredClone(diary),entryId});activeBook().entries=entries;delete activeBook().draft;activeBook().updated=new Date().toISOString();return store('wd-books',books)}
const surface=$('#scrap-surface');
const legacy=read('wd-draft',{});
let diary=structuredClone(ensureSpreads(activeBook()).diary||{left:'',right:''});
function renderDiary(){window.diaryPaper?.sync();document.querySelectorAll('.diary-writing textarea').forEach(el=>el.readOnly=isReadOnlyBook());$('#diary-left').value=diary.left||'';$('#diary-right').value=diary.right||'';renderPageNavigation();}
renderDiary();
document.querySelectorAll('.diary-writing textarea').forEach(el=>{el.addEventListener('focus',()=>selectPiece(null));el.oninput=()=>{if(!requireBookEdit()){renderDiary();return}diary={left:$('#diary-left').value,right:$('#diary-right').value};saveDraft()}});

function saveDraft(){const ok=persistLibrary();if(isReadOnlyBook())$('#saved-status').textContent='Read-only';else if(!ok)$('#saved-status').textContent='Changes not saved';else if(!window.diaryAuth?.user)$('#saved-status').textContent='Saved on this browser';$('#book').classList.toggle('has-pieces',pieces.length>0);window.fitDiaryPieces?.();return ok}
function changeView(view){if(view==='entries'){window.showBookContents?.();return}if(view!=='diary')window.leaveBookFullscreen?.();if(view!=='diary')window.voiceSession?.stop();window.stopDiaryDictation?.();window.cancelDiaryTurn?.();if(view!=='diary')window.exitBookDesk?.();else if(document.querySelector('#book').classList.contains('book-open')||window.voiceSession?.active)window.enterBookDesk?.();document.querySelectorAll('#scrap-surface video,#scrap-surface audio').forEach(media=>media.pause());['diary','memories','entries','books'].forEach(v=>{$('#'+v+'-view').hidden=v!==view;document.querySelector(`[data-view="${v}"]`)?.classList.toggle('active',v===view)});if(view==='memories')renderMemories();if(view==='entries')renderEntries();if(view==='books')renderBooks();selectPiece(null)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
function openBook(){if(!$('#book').classList.contains('book-open'))window.enterBookFullscreen?.();window.enterBookDesk?.();window.requestAnimationFrame(()=>window.fitDiaryBook?.());$('#book').classList.remove('book-closed');$('#book').classList.add('book-open');$('#cover').classList.add('open');$('#cover').setAttribute('aria-expanded','true');$('.diary-writing').inert=false;$('#scrap-surface').inert=false;}
function closeBook(){window.cancelDiaryTurn?.();document.querySelectorAll('#scrap-surface video,#scrap-surface audio').forEach(media=>media.pause());selectPiece(null);$('#cover').classList.remove('open');$('#book').classList.remove('book-open');$('#book').classList.add('book-closed');$('#cover').setAttribute('aria-expanded','false');$('#scrap-surface').inert=true;window.requestAnimationFrame(()=>window.fitDiaryBook?.());}
$('#cover').onclick=openBook;$('#close-book').onclick=closeBook;$('.hero-cta').onclick=e=>{e.preventDefault();exploreSample();openBook();document.querySelector('#diary-view').scrollIntoView({behavior:'smooth',block:'start'})};
function newPiece(type,text='',url='',mediaType=''){if(!requireBookEdit())return null;openBook();const p={id:crypto.randomUUID(),type,text,url,mediaType,x:12+(pieces.length%4)*12,y:12+(pieces.length%3)*15,w:type==='audio'?39:type==='photo'||type==='video'?28:24,tilt:pieces.length%2?-4:3,color:({note:'#f8ed89',paper:'#fffdf6',cardboard:'#cba77a',ticket:'#e7d9f2',tape:'#d6c4ea',photo:'#ffffff',video:'#ffffff',audio:'#e7d9f2'})[type]||'#fffdf6',font:27};pieces.push(p);renderPieces();selectPiece(p.id);saveDraft();window.voiceSession?.onPieceCreated(p);return p}
function selectPiece(id){if(isReadOnlyBook())id=null;selected=id;window.selectDiaryVoicePiece?.(id);document.querySelectorAll('.scrap-piece').forEach(el=>{el.classList.toggle('selected',el.dataset.id===id);});$('#piece-tools').hidden=!id;const p=pieces.find(p=>p.id===id);if(p){$('#piece-color').value=p.color;$('#piece-size').value=p.font;$('#piece-tilt').value=p.tilt}}
function stylePiece(el,p){el.style.left=p.x+'%';el.style.top=p.y+'%';el.style.width=p.w+'%';el.style.setProperty('--tilt',p.tilt+'deg');el.style.setProperty('--piece-color',p.color);el.querySelector('.piece-text').style.fontSize=p.font+'px'}
function renderPieces(){window.stopDiaryDictation?.();surface.querySelectorAll('video,audio').forEach(media=>media.pause());surface.querySelectorAll('.scrap-piece').forEach(el=>el.remove());pieces.forEach(p=>{const el=document.createElement('article');el.className='scrap-piece '+p.type;el.dataset.id=p.id;el.tabIndex=0;el.setAttribute('aria-label',p.type+' scrapbook piece. Use arrow keys to move.');if(p.type==='note'){const number=pieces.filter(item=>item.type==='note').findIndex(item=>item.id===p.id)+1;el.dataset.noteNumber=number;el.setAttribute('aria-label','Sticky note '+number+'. Use its grip to move or click its text to edit.')}const handle=document.createElement('button');handle.className='piece-handle';handle.textContent='⠿';handle.setAttribute('aria-label','Move '+p.type+' piece');el.append(handle);if(p.url){const media=document.createElement(p.type==='audio'?'audio':p.type==='video'?'video':'img');media.src=p.url;if(p.type==='video'||p.type==='audio'){media.controls=true;media.preload='metadata';media.setAttribute('aria-label',p.type==='video'?'Play video memory':'Play voice note');}else{media.alt=p.text||'Your photo memory';media.draggable=false}el.append(media)}const content=document.createElement('div');content.className='piece-text';content.contentEditable=String(!isReadOnlyBook());content.tabIndex=isReadOnlyBook()?-1:0;content.title='Click to write. Use the grip above to move this piece.';content.ondblclick=()=>{if(!requireBookEdit())return;content.contentEditable='true';content.focus()};content.setAttribute('role','textbox');content.setAttribute('aria-label','Edit '+p.type+' text');content.dataset.placeholder=({note:'A little thought…',paper:'Your words go here…',cardboard:'Something to keep…',ticket:'Admit one: a good day',tape:'',photo:'Add a caption…',video:'Add a caption…',audio:'A voice worth keeping…'})[p.type];content.textContent=p.text;content.oninput=()=>{if(!requireBookEdit()){content.textContent=p.text;return}p.text=content.innerText??content.textContent;saveDraft()};el.append(content);const resize=document.createElement('button');resize.className='resize-piece';resize.textContent='◢';resize.setAttribute('aria-label','Resize piece');el.append(resize);el.onpointerdown=e=>{selectPiece(p.id)};el.onfocusin=()=>selectPiece(p.id);el.onkeydown=e=>{if(e.target.closest('[contenteditable]'))return;const step=e.shiftKey?5:1;const axis={ArrowLeft:['x',-step],ArrowRight:['x',step],ArrowUp:['y',-step],ArrowDown:['y',step]}[e.key];if(axis){if(!requireBookEdit())return;e.preventDefault();p[axis[0]]=Math.max(0,Math.min(axis[0]==='x'?100-p.w:85,p[axis[0]]+axis[1]));stylePiece(el,p);saveDraft()}};
function pointer(e,resizing){if(e.button!==0||!requireBookEdit())return;e.preventDefault();e.stopPropagation();selectPiece(p.id);const r=surface.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,x=parseFloat(el.style.left)||0,y=parseFloat(el.style.top)||0,w=p.w;const target=e.target.closest('.piece-text')||e.currentTarget;target.setPointerCapture(e.pointerId);let moved=false;el.classList.add('dragging');const move=ev=>{const dx=ev.clientX-startX,dy=ev.clientY-startY;if(Math.hypot(dx,dy)<3&&!moved)return;moved=true;if(resizing){p.w=Math.min(85,Math.max(16,w+dx/r.width*100));p.x=Math.min(p.x,100-Math.max(p.w,el.offsetWidth/r.width*100))}else{const maxX=Math.max(0,100-el.offsetWidth/r.width*100),maxY=Math.max(0,100-el.offsetHeight/r.height*100);p.x=Math.max(0,Math.min(maxX,x+dx/r.width*100));p.y=Math.max(0,Math.min(maxY,y+dy/r.height*100))}stylePiece(el,p)};const stop=()=>{el.classList.remove('dragging');target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',stop);target.removeEventListener('pointercancel',stop);if(target.hasPointerCapture(e.pointerId))target.releasePointerCapture(e.pointerId);saveDraft()};target.addEventListener('pointermove',move);target.addEventListener('pointerup',stop);target.addEventListener('pointercancel',stop)}handle.hidden=isReadOnlyBook();resize.hidden=isReadOnlyBook();handle.onpointerdown=e=>pointer(e,false);resize.onpointerdown=e=>pointer(e,true);stylePiece(el,p);surface.append(el)});$('#book').classList.toggle('has-pieces',pieces.length>0);if(selected)selectPiece(selected)}
surface.addEventListener('pointerdown',e=>{if(e.target===surface||e.target.closest('.spread-empty')||e.target.closest('.diary-writing'))selectPiece(null)});
