function editPiece(field,value){if(!requireBookEdit())return;const p=pieces.find(p=>p.id===selected);if(!p)return;p[field]=value;const el=surface.querySelector(`[data-id="${p.id}"]`);stylePiece(el,p);saveDraft()}
