$('#start-voice').onclick=()=>{openBook();$('#diary-left').focus();window.startDiaryVoice?.();};$('#voice-form').onsubmit=e=>{e.preventDefault();const text=$('#voice-text').value.trim();if(!text)return;newPiece('paper',text);$('#voice-dialog').close();e.target.reset();toast('Your words are on the page. Move them wherever you like.')};
async function addDiaryMedia(files,audioOnly=false){if(!requireBookEdit())return 0;const uploadBook=activeBook().id,uploadSpread=ensureSpreads(activeBook()).id,uploadRight=(window.bookControls?.currentPage()||1)%2===0;let added=0;for(const file of files){let type=file.type||'';const ext=file.name.split('.').pop().toLowerCase();if(!type||type==='application/octet-stream')type=({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg',oga:'audio/ogg',aac:'audio/aac',flac:'audio/flac',opus:'audio/ogg'})[ext]||type;if(!/^(image|video|audio)\//.test(type)||audioOnly&&!type.startsWith('audio/')){toast(audioOnly?'Choose an MP3, WAV, M4A, OGG, AAC, or FLAC recording.':'Choose a photo, video, or audio recording.');continue}if(file.size>2*1024*1024){toast('Choose a file up to 2 MB for this local diary.');continue}try{const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});if(activeBook().id!==uploadBook||ensureSpreads(activeBook()).id!==uploadSpread){toast('The pages changed while the file was loading. Choose it again on the intended page.');continue}const audio=type.startsWith('audio/'),piece=newPiece(audio?'audio':type.startsWith('video/')?'video':'photo',audio?file.name.replace(/\.[^.]+$/,''):'',url,type);if(audio){piece.font=18;piece.x=uploadRight?55:7;piece.y=45;piece.w=39;stylePiece(surface.querySelector('[data-id="'+piece.id+'"]'),piece);selectPiece(piece.id);saveDraft();$('#session-feedback').textContent='Voice recording added. Press play on the page, or speak to change its caption.'}added++}catch{toast('Could not read this file. Try another.')}}return added}
$('#add-photo').onclick=()=>$('#media-file').click();$('#media-file').onchange=async e=>{await addDiaryMedia(e.target.files);e.target.value='';e.target.accept='image/*,video/*,audio/*'};
$('#save-spread').onclick=()=>{if(!requireBookEdit())return;if(!pieces.length&&!diary.left.trim()&&!diary.right.trim()){toast('Write a little about your day first.');return}const text=[diary.left,diary.right,...pieces.map(p=>p.text)].filter(Boolean).join('\n\n');const entry={id:entryId||Date.now(),spreadId:ensureSpreads(activeBook()).id,title:text.split('\n')[0]?.slice(0,65)||'A little collection of today',text,diary:structuredClone(diary),pieces:structuredClone(pieces),date:new Date().toISOString()};const next=[entry,...entries.filter(e=>e.id!==entry.id)];if(store('wd-entries',next)){entries=next;entryId=entry.id;persistLibrary();toast('This day is kept in '+activeBook().title+'.')}};
function renderEntries(){const root=$('#entry-list');root.replaceChildren();if(!entries.length){const p=document.createElement('p');p.className='empty';p.textContent='Your first diary entry is waiting.';root.append(p)}entries.forEach(entry=>{const btn=document.createElement('button');btn.className='entry-card';const date=document.createElement('small');date.textContent=new Date(entry.date).toLocaleDateString('en-IN');const h=document.createElement('h3');h.textContent=entry.title;const p=document.createElement('p');p.textContent=entry.text?.slice(0,160)||'A day in your diary.';btn.append(date,h,p);btn.onclick=()=>{persistLibrary();let index=activeBook().spreads.findIndex(s=>s.id===entry.spreadId);if(index<0){activeBook().spreads.push({id:crypto.randomUUID(),heading:entry.title,diary:structuredClone(entry.diary||{left:entry.text||'',right:''}),pieces:structuredClone(entry.pieces||[]),entryId:entry.id});index=activeBook().spreads.length-1;entry.spreadId=activeBook().spreads[index].id}activeBook().activeSpread=index;entryId=entry.id;diary=entry.diary?structuredClone(entry.diary):{left:entry.pieces?'':entry.text||'',right:''};renderDiary();pieces=entry.pieces?structuredClone(entry.pieces):[...(entry.media||[]).map((m,i)=>({id:crypto.randomUUID(),type:m.type.startsWith('video/')?'video':'photo',url:m.url,text:'',x:52,y:10+i*15,w:28,tilt:3,color:'#ffffff',font:22}))];changeView('diary');openBook();renderPieces();saveDraft();document.querySelector('#diary-view').scrollIntoView({behavior:'smooth',block:'start'})};root.append(btn)})}
