bookLabels();closeBook();
renderPieces();renderMemories();


window.libraryBridge={get:()=>({books:structuredClone(books),memories:structuredClone(memories)}),set:payload=>{window.cloudHydrating=true;try{books=payload?.books?.length?structuredClone(payload.books).filter(book=>!book.isSample):[];memories=structuredClone(payload?.memories||[]);books.forEach(ensureSpreads);let intro=books.find(b=>b.isSample&&b.sampleVersion===DEMO_VERSION);if(!intro){intro=createSampleBook();books.push(intro)}intro.activeSpread=0;activeBookId=intro.id;entries=activeBook().entries||[];pieces=structuredClone(ensureSpreads(activeBook()).pieces||[]);diary=structuredClone(ensureSpreads(activeBook()).diary||{left:'',right:''});entryId=ensureSpreads(activeBook()).entryId||null;store('wd-books',books);store('wd-memories',memories);store('wd-active-book',activeBookId);renderDiary();renderPieces();renderMemories();bookLabels();closeBook();changeView('diary')}finally{window.cloudHydrating=false}}};



function renderPageNavigation(){const book=activeBook(),spread=ensureSpreads(book),i=book.activeSpread;document.querySelector('#book').classList.toggle('sample-reading',!!book.isSample);document.querySelector('#book').classList.toggle('read-only-book',isReadOnlyBook(book));window.refreshBookAccess?.();const picker=$('#spread-select');picker.replaceChildren();book.spreads.forEach((s,index)=>picker.add(new Option('Pages '+(index*2+1)+'–'+(index*2+2)+(s.heading?' · '+s.heading:''),String(index))));picker.value=String(i);$('#previous-spread').disabled=i===0;$('#next-spread').disabled=!!book.isSample&&i===book.spreads.length-1;$('#spread-heading').value=spread.heading||'';const headers=document.querySelectorAll('.diary-page-date');headers[0].replaceChildren(document.createTextNode(spread.heading||'YOUR DAY'));const left=document.createElement('span');left.textContent=String(i*2+1).padStart(2,'0');headers[0].append(left);headers[1].replaceChildren(document.createTextNode('YOUR STORY, CONTINUED'));const right=document.createElement('span');right.textContent=String(i*2+2).padStart(2,'0');headers[1].append(right);}
function commitSpread(index){persistLibrary();const book=activeBook();book.activeSpread=Math.max(0,Math.min(book.spreads.length-1,index));const spread=ensureSpreads(book);pieces=structuredClone(spread.pieces||[]);diary=structuredClone(spread.diary||{left:'',right:''});entryId=spread.entryId||null;selectPiece(null);renderDiary();renderPieces();saveDraft();openBook();}
function goToSpread(index){window.stopDiaryDictation?.();const target=Math.max(0,Math.min(activeBook().spreads.length-1,index));if(window.turnDiaryPage)window.turnDiaryPage(target,()=>commitSpread(target));else commitSpread(target);}
function addSpread(){if(!requireBookEdit()||document.querySelector('.page-turn-layer'))return;persistLibrary();const book=activeBook();book.spreads.push({id:crypto.randomUUID(),heading:'',diary:{left:'',right:''},pieces:[],entryId:null});goToSpread(book.spreads.length-1);toast('Two fresh pages added. Keep going whenever you need more room.');}
$('#previous-spread').onclick=()=>goToSpread(activeBook().activeSpread-1);$('#next-spread').onclick=()=>activeBook().activeSpread===activeBook().spreads.length-1?addSpread():goToSpread(activeBook().activeSpread+1);$('#spread-select').onchange=e=>goToSpread(+e.target.value);$('#add-spread').onclick=addSpread;$('#spread-heading').oninput=e=>{if(!requireBookEdit()){renderPageNavigation();return;}ensureSpreads(activeBook()).heading=e.target.value;persistLibrary()};$('#spread-heading').onchange=renderPageNavigation;
$('#customize-current').onclick=()=>bookDialog(activeBookId);
function previewCoverImage(){$('#cover-image-preview').hidden=!coverImageDraft;$('#cover-image-preview').src=coverImageDraft;$('#remove-cover-image').hidden=!coverImageDraft;}
$('#book-image').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>1024*1024){toast('Choose an image under 1 MB for your cover.');e.target.value='';return}try{coverImageDraft=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=rej;reader.readAsDataURL(file)});$('#book-style').value='photo';previewCoverImage()}catch{toast('Could not read that image. Try another.')}};$('#remove-cover-image').onclick=()=>{coverImageDraft='';$('#book-image').value='';previewCoverImage()};
function exploreSample(){let sample=books.find(b=>b.isSample&&b.sampleVersion===DEMO_VERSION);if(!sample){sample=createSampleBook();books.push(sample);store('wd-books',books)}showBook(sample.id);toast('A few little moments. Write, play a clip, or hear a voice note.');}
$('#explore-sample').onclick=exploreSample;



document.querySelectorAll("[data-tour]").forEach(b=>b.onclick=()=>{goToSpread(Number(b.dataset.tour));document.querySelector("#book").scrollIntoView({behavior:"smooth",block:"start"})});

